<?php
require_once dirname(__DIR__) . '/app/helpers.php';
require_once dirname(__DIR__) . '/app/Services/BeneficiaryService.php';
require_once dirname(__DIR__) . '/app/Services/AccountService.php';
require_auth();
$user=auth_user();$db=Database::connection();$svc=new BeneficiaryService($db);$accountService=new AccountService($db);$error=null;$success=null;
try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='add'){$svc->create((int)$user['id'],$_POST['name']??'',$_POST['account_number']??'',$_POST['bank_name']??'',$_POST['nickname']??null);$success=t('Beneficiary verified and added successfully.');}elseif($action==='disable'){$svc->disable((int)$user['id'],$id);$success=t('Beneficiary disabled.');}elseif($action==='enable'){$svc->enable((int)$user['id'],$id);$success=t('Beneficiary re-enabled.');}elseif($action==='delete'){$svc->delete((int)$user['id'],$id);$success=t('Beneficiary removed.');}}}catch(Throwable $e){$error=$e->getMessage();}
$items=$svc->list((int)$user['id']);$totalBalance=$accountService->getTotalBalance((int)$user['id']);$pageTitle=t('Beneficiaries');$currentPage='beneficiaries';require __DIR__.'/partials/header.php';require __DIR__.'/partials/sidebar.php';
?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h3 class="fw-bold mb-1"><?=e(t('Beneficiaries'))?></h3><p class="text-muted mb-0"><?=e(t('Save verified CommServe accounts for quick transfers.'))?></p></div><a href="<?=url('transfer.php')?>?type=beneficiary" class="btn btn-primary"><i class="bi bi-send me-2"></i><?=e(t('Send to Beneficiary'))?></a></div>
