<div class="col-lg-8"><div class="card border-0 shadow-sm"><div class="card-header bg-white d-flex justify-content-between align-items-center"><h6 class="fw-bold mb-0"><?=e(t('Your Beneficiaries'))?> (<?=count($items)?>)</h6><span class="badge text-bg-light border"><?=e(t('Active'))?>: <?=count(array_filter($items,fn($b)=>$b['status']==='active'))?></span></div><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th><?=e(t('Verified Holder'))?></th><th><?=e(t('Account'))?></th><th><?=e(t('Nickname'))?></th><th><?=e(t('Status'))?></th><th><?=e(t('Added'))?></th><th><?=e(t('Actions'))?></th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="6" class="text-center text-muted py-5"><?=e(t('No beneficiaries yet.'))?></td></tr><?php else:foreach($items as $b):?><tr><td><div class="fw-semibold"><?=e($b['name'])?></div><div class="small text-success"><i class="bi bi-patch-check-fill me-1"></i><?=e(t('Verified'))?></div></td><td class="font-monospace"><?=e($b['account_number'])?><div class="small text-muted"><?=e($b['bank_name'])?></div></td><td><?=e($b['nickname']??'—')?></td><td><span class="badge <?=$b['status']==='active'?'text-bg-success':'text-bg-secondary'?>"><?=e(tx_label($b['status']))?></span><?php if(($b['account_status']??'')!=='active'):?><div class="small text-danger mt-1"><?=e(t('Account inactive'))?></div><?php endif;?></td><td class="small text-muted"><?=e(format_date($b['created_at']))?></td><td><div class="d-flex gap-1 flex-wrap"><?php if($b['status']==='active'&&($b['account_status']??'')==='active'):?><a href="<?=url('transfer.php')?>?type=beneficiary&beneficiary=<?=$b['id']?>" class="btn btn-sm btn-primary"><?=e(t('Send'))?></a><form method="post" onsubmit="return confirm('Disable this beneficiary?')"><?=csrf_field()?><input type="hidden" name="action" value="disable"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="btn btn-sm btn-outline-danger"><?=e(t('Disable'))?></button></form><?php elseif($b['status']==='disabled'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="enable"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="btn btn-sm btn-outline-success"><?=e(t('Enable'))?></button></form><?php endif;?><form method="post" onsubmit="return confirm('Remove this beneficiary permanently? This cannot be undone.')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="btn btn-sm btn-outline-secondary"><?=e(t('Delete'))?></button></form></div></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="card border-0 bg-light mt-4"><div class="card-body p-3 small text-muted"><i class="bi bi-shield-check me-2"></i><?=e(t('Beneficiary transfers require Transaction PIN and OTP. Create, enable, disable and delete actions are audit logged.'))?></div></div></div></div>
